import { useQuery } from '@tanstack/react-query';
import { fetchJson } from '../../../shared/api/fetchClient';
import { queryKeys } from '../../../shared/api/queryKeys';

interface PatientSummary {
  patientCode: string;
  firstName: string;
  lastName: string;
  dateOfBirth: string;
  insurancePlanCode?: string;
  insuranceProvider?: string;
}

interface ProviderSummary {
  providerCode: string;
  fullName: string;
  specialty: string;
  officeRoom?: string;
  preferredContact?: string;
}

export interface Appointment {
  id: number;
  appointmentUid: string;
  appointmentCode: string;
  status: string;
  startTime: string;
  endTime: string;
  patient: PatientSummary;
  provider: ProviderSummary;
  roomCode?: string;
  legacyNotes?: string;
}

export interface PagedAppointments {
  content: Appointment[];
  page: number;
  size: number;
  totalElements: number;
  totalPages: number;
  first: boolean;
  last: boolean;
}

interface UseAppointmentsOptions {
  page?: number;
  size?: number;
  status?: string;
}

export const useAppointments = (options: UseAppointmentsOptions = {}) => {
  const { page = 0, size = 10, status } = options;

  return useQuery({
    queryKey: queryKeys.appointments.list(page, size, status),
    queryFn: async () => {
      const params = new URLSearchParams({
        page: page.toString(),
        size: size.toString(),
        ...(status && { status }),
      });
      const data = await fetchJson<PagedAppointments>(`/api/appointments?${params}`);
      return data;
    },
  });
};
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { graphqlClient } from '../../../shared/api/graphql/client';
import { queryKeys } from '../../../shared/api/queryKeys';

const CREATE_APPOINTMENT_MUTATION = `
  mutation CreateAppointment($request: AppointmentInput!) {
    createAppointment(request: $request) {
      id
      appointmentUid
      status
      startTime
      endTime
      roomCode
    }
  }
`;

interface AppointmentInput {
  patientCode: string;
  providerCode: string;
  appointmentType?: string;
  startTime: string;
  endTime: string;
  roomCode?: string;
}

interface CreateAppointmentData {
  createAppointment: {
    id: string;
    appointmentUid: string;
    status: string;
    startTime?: string;
    endTime?: string;
    roomCode?: string;
  };
}

export const useBookAppointment = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (input: AppointmentInput) => {
      const data = await graphqlClient.request<CreateAppointmentData>(
        CREATE_APPOINTMENT_MUTATION,
        { request: input }
      );
      return data.createAppointment;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: queryKeys.appointments.all });
      queryClient.invalidateQueries({ queryKey: queryKeys.dashboard.stats() });
    },
  });
};
